"""最小复现 v2：嵌套 compile（外层 block_forward + 内层 quant_func）× 活 hook × autocast。

模拟 auto-round tuning 的真实结构：
- W = WrapperLinear 类比：内层 compiled quant_func + F.linear 用 orig 权重（hook 死）
- Skip = 被 ignore 的层：以模块调用执行，hook 活，跨卡搬移
"""
import sys
import torch
from torch import nn
from torch.amp import autocast
from torch.nn import functional as F

USE_HOOKS = "--hooks" in sys.argv
USE_NESTED_COMPILE = "--nested" in sys.argv


def quant_func(w):
    return w * 1.001


class W(nn.Module):
    """WrapperLinear 类比。"""

    def __init__(self, lin):
        super().__init__()
        self.orig_layer = lin
        self.qf = torch.compile(quant_func) if USE_NESTED_COMPILE else quant_func

    def forward(self, x):
        dev = self.orig_layer.tuning_device
        x = x.to(dev)
        w = self.qf(self.orig_layer.weight)
        return F.linear(x, w)


class Block(nn.Module):
    def __init__(self):
        super().__init__()
        self.q1 = W(nn.Linear(256, 256, bias=False))
        self.skip = nn.Linear(256, 256, bias=False)  # 活 hook 的 ignore 层
        self.q2 = W(nn.Linear(256, 256, bias=False))

    def forward(self, x):
        return self.q2(self.skip(self.q1(x)))


def block_forward(block, x):
    with autocast(device_type="cuda", dtype=torch.bfloat16):
        return block(x)


def main():
    torch.manual_seed(0)
    block = Block().cuda(0)
    if USE_HOOKS:
        from accelerate.hooks import AlignDevicesHook, add_hook_to_module
        mods = {"q1.orig_layer": "cuda:0", "skip": "cuda:1", "q2.orig_layer": "cuda:0"}
        for name, dev in mods.items():
            mod = block
            for part in name.split("."):
                mod = getattr(mod, part)
            mod.to(dev)
            mod.tuning_device = dev
            add_hook_to_module(mod, AlignDevicesHook(dev, io_same_device=True), True)
        print("hooks:", mods, flush=True)

    compiled = torch.compile(block_forward)
    for it in range(2):
        x = torch.randn(8, 256, device="cuda:0")
        out = compiled(block, x)
        loss = out.float().pow(2).mean()
        loss.backward()
        print(f"iter {it}: loss={loss.item():.6f} OK", flush=True)
    print("REPRO-TEST DONE")


if __name__ == "__main__":
    main()

