"""把逐专家 packed 键重堆成 stacked（vllm 标准 MoE mxfp4 布局）。"""
import glob, json, os, re, sys
import torch
from safetensors import safe_open
from safetensors.torch import save_file

SRC=sys.argv[1]; DST=sys.argv[2]
EXP_RE = re.compile(r"^(.*feed_forward\.experts)\.(\d+)\.(w13_weight|w2_weight)\.(weight_packed|weight_scale)$")

# 收集全量键
idx=json.load(open(f"{SRC}/model.safetensors.index.json"))
wm=idx['weight_map']
groups={}   # (prefix, kind, suffix) -> {expert_id: (key, shard)}
plain={}
for k,shard in wm.items():
    m=EXP_RE.match(k)
    if m:
        groups.setdefault((m.group(1),m.group(3),m.group(4)),{})[int(m.group(2))]=(k,shard)
    else:
        plain[k]=shard
print(f"stack 组: {len(groups)}, 普通键: {len(plain)}", flush=True)

# 读所有需要的张量
out={}
need=set()
for g in groups.values(): need.update(k for k,_ in g.values())
cache={}
for shard in sorted(set(wm[k] for k in list(need)+list(plain))):
    with safe_open(f"{SRC}/{shard}", framework='pt') as h:
        for k in h.keys():
            if k in need or k in plain: cache[k]=h.get_tensor(k)
for k in plain: out[k]=cache[k]
for (prefix,kind,suffix),experts in sorted(groups.items()):
    ids=sorted(experts)
    stacked=torch.stack([cache[experts[i][0]] for i in ids], dim=0)
    out[f"{prefix}.{kind}.{suffix}"]=stacked.contiguous()
    print(f"stacked {prefix}.{kind}.{suffix}: {tuple(stacked.shape)}", flush=True)

# 写单分片（L3 够小）
os.makedirs(DST, exist_ok=True)
save_file(out, f"{DST}/model.safetensors", metadata={'format':'pt'})
wm_out={k:"model.safetensors" for k in out}
total=sum(t.numel()*t.element_size() for t in out.values())
json.dump({"metadata":{"total_size":total},"weight_map":wm_out}, open(f"{DST}/model.safetensors.index.json","w"), indent=2)
import shutil
for f in os.listdir(SRC):
    if not f.endswith('.safetensors') and f!='model.safetensors.index.json':
        s=f"{SRC}/{f}"; d=f"{DST}/{f}"
        if os.path.isfile(s): shutil.copy2(s,d)
        elif os.path.isdir(s): shutil.copytree(s,d,dirs_exist_ok=True)
print("DONE", flush=True)
