def push_references(self, from_dir: Path, *, auto_round_ref: str = "",
                    note: str = "", file: str | None = None) -> bool:
    """Stage reference docs (+ MANIFEST) and push.

    Default is whole-tree replace (``from_dir`` becomes the new
    ``references/``); pass ``file=`` for an **incremental** update of a
    single doc — only that file's per-file freshness entry is bumped, the
    rest of the tree is untouched.  ``auto_round_ref`` records which
    auto-round version/commit the pushed docs were verified against —
    the freshness signal owners check before trusting the knowledge on a
    newer upstream (structure: ``knowledge_layout.yaml``).
    """
    from_dir = Path(from_dir)
    if not from_dir.is_dir():
        raise ValueError(f"references source dir not found: {from_dir}")
    dest = self.references_dir
    now = time.strftime("%Y-%m-%dT%H:%M:%S%z")
    if file is not None:
        src = from_dir / file
        if not src.is_file():
            raise ValueError(f"{file} not found in {from_dir}")
        dest.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dest / src.name)
        manifest = self._read_references_manifest()
        files = manifest.get("files")
        files = {f: {} for f in files} if isinstance(files, list) else (files or {})
        files[src.name] = {"auto_round_ref": auto_round_ref
                           or manifest.get("auto_round_ref", ""),
                           "updated_at": now,
                           "scope": note}
        manifest.update({"updated_at": now, "note": note, "files": files})
        if auto_round_ref:
            manifest["auto_round_ref"] = auto_round_ref
        (dest / "MANIFEST.json").write_text(json.dumps(manifest, indent=2))
        return self.push_up()
    if dest.exists():
        shutil.rmtree(dest)
    shutil.copytree(from_dir, dest)
    manifest = {
        "updated_at": now,
        "auto_round_ref": auto_round_ref,
        "note": note,
        "files": {p.name: {"auto_round_ref": auto_round_ref, "updated_at": now,
                           "scope": ""}
                  for p in dest.iterdir() if p.is_file() and p.name != "MANIFEST.json"},
    }
    (dest / "MANIFEST.json").write_text(json.dumps(manifest, indent=2))
    return self.push_up()

def _read_references_manifest(self) -> dict:
    try:
        return json.loads((self.references_dir / "MANIFEST.json").read_text())
    except (OSError, json.JSONDecodeError):
        return {}

